import{_ as t,o as s,c as a,ah as n}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/architecture.md","filePath":"src/en/guide/architecture.md"}'),o={name:"en/guide/architecture.md"};function r(d,e,i,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Kura is a <strong>monolithic Laravel</strong> application rendered client-side with Inertia and Vue. There is no dedicated mobile API: mobile access goes through Sève&#39;s Moodle app.</p><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th></tr></thead><tbody><tr><td>Language</td><td>PHP 8.3</td></tr><tr><td>Framework</td><td>Laravel 13</td></tr><tr><td>Rendering</td><td>Inertia v3 + Vue 3 (TypeScript)</td></tr><tr><td>Styling</td><td>Tailwind CSS v4, shadcn-vue components, Phosphor icons</td></tr><tr><td>Web authentication</td><td>Laravel Fortify (session, 2FA, passkeys) — no public registration</td></tr><tr><td>API</td><td>Laravel Sanctum (tokens)</td></tr><tr><td>OAuth2 / OIDC</td><td>Laravel Passport — Kura is Sève&#39;s identity provider</td></tr><tr><td>Roles</td><td><code>spatie/laravel-permission</code></td></tr><tr><td>PDF</td><td><code>barryvdh/laravel-dompdf</code></td></tr><tr><td>Spreadsheets</td><td><code>openspout/openspout</code></td></tr><tr><td>Typed routes</td><td>Laravel Wayfinder (frontend)</td></tr><tr><td>Tests</td><td>Pest 4, Pest Plugin Laravel</td></tr><tr><td>Quality</td><td>Pint, Larastan level 7, ESLint, Prettier, <code>vue-tsc</code></td></tr><tr><td>Database</td><td>SQLite locally, MySQL in staging and production</td></tr></tbody></table><h2 id="high-level-view" tabindex="-1">High-level view <a class="header-anchor" href="#high-level-view" aria-label="Permalink to &quot;High-level view&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> NextBoxx website (stateless)                              Sève (Moodle LTS)</span></span>
<span class="line"><span>        │  POST /api/candidatures (API key)                  ▲   │</span></span>
<span class="line"><span>        ▼                                                    │   │</span></span>
<span class="line"><span> ┌───────────────────────────────┐   OAuth2 / OIDC (SSO)     │   │</span></span>
<span class="line"><span> │ Kura (kura-web)               │◄──────────────────────────┘   │</span></span>
<span class="line"><span> │ Laravel + Inertia + Vue       │   Moodle web services:         │</span></span>
<span class="line"><span> │ admin/finance source of truth │   provisioning, attendance,    │</span></span>
<span class="line"><span> │                               │   grades, partners             │</span></span>
<span class="line"><span> │                               │───────────────────────────────►│</span></span>
<span class="line"><span> └───────────────────────────────┘◄───────────────────────────────┘</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> Email · WhatsApp · online payment · private PDF storage</span></span></code></pre></div><p>Kura is the source of truth for identity, statuses, candidatures, enrolments, billing, certification and payouts. Sève is the source of truth for contents, detailed attendance, results and messaging.</p><h2 id="repository-structure" tabindex="-1">Repository structure <a class="header-anchor" href="#repository-structure" aria-label="Permalink to &quot;Repository structure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app/</span></span>
<span class="line"><span>  Actions/            Fortify and user actions</span></span>
<span class="line"><span>  Concerns/           Reusable traits (yearly references, PDF sealing, password rules)</span></span>
<span class="line"><span>  Console/Commands/   Scheduled commands (billing:run, seve:sync, cohorts:advance…)</span></span>
<span class="line"><span>  Enums/              Domain statuses and typologies (≈ 60 enums)</span></span>
<span class="line"><span>  Http/Controllers/   Controllers grouped by module (Admin, Billing, Cohorts, Documents…)</span></span>
<span class="line"><span>  Http/Middleware/    AuthenticateSiteKey, EnsureSeveAccess, SetLocale, HandleInertiaRequests</span></span>
<span class="line"><span>  Listeners/          Login and notification delivery logging</span></span>
<span class="line"><span>  Models/             Eloquent models (≈ 60)</span></span>
<span class="line"><span>  Notifications/      Email, Sève and WhatsApp notifications</span></span>
<span class="line"><span>  Providers/          AppServiceProvider: Gates, Passport, defaults</span></span>
<span class="line"><span>  Services/           Extracted business logic (documents, Sève, WhatsApp, reporting, direction)</span></span>
<span class="line"><span>routes/               One file per module: web, api, oauth, billing, cohorts, documents…</span></span>
<span class="line"><span>resources/js/</span></span>
<span class="line"><span>  pages/              Inertia pages (≈ 85), one folder per module</span></span>
<span class="line"><span>  components/         Reusable components (UI, candidatures, billing, cohorts…)</span></span>
<span class="line"><span>  layouts/            AppLayout, AuthLayout, PublicLayout…</span></span>
<span class="line"><span>  composables/        useAccess, useMainNav, useLocale, useAppearance…</span></span>
<span class="line"><span>  lib/                Per-domain formatting and labels (billing.ts, enrolments.ts…)</span></span>
<span class="line"><span>  types/              TypeScript types for Inertia props</span></span>
<span class="line"><span>  actions/ routes/    Generated Wayfinder functions</span></span>
<span class="line"><span>tests/</span></span>
<span class="line"><span>  Feature/            HTTP and business-flow tests, one folder per module</span></span>
<span class="line"><span>  Unit/               Targeted unit tests</span></span>
<span class="line"><span>deploy/cpanel/        Deployment scripts (install.sh, deploy.sh, crontab.example)</span></span></code></pre></div><h2 id="request-lifecycle" tabindex="-1">Request lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request lifecycle&quot;">​</a></h2><ol><li><strong>Routing</strong>: routes are split by module under <code>routes/</code>, then loaded by <code>routes/web.php</code>.</li><li><strong>Middleware</strong>: <code>auth</code>, <code>verified</code>, <code>can:*</code>, <code>site.key</code> (website API), <code>throttle:*</code>, <code>signed</code> (public links), <code>SetLocale</code>.</li><li><strong>Controller</strong>: validates the request (Form Requests), authorises the action (<code>Gate::authorize</code> or <code>abort_unless</code>), runs the business logic and returns an Inertia page or a file.</li><li><strong>Inertia props</strong>: <code>HandleInertiaRequests</code> shares the user, their roles and the <code>can*</code> booleans consumed by <code>useAccess</code>.</li><li><strong>Vue</strong>: the page receives typed props, uses shared components and Wayfinder for URLs.</li></ol><h2 id="data-model" tabindex="-1">Data model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data model&quot;">​</a></h2><p>The full relational model lives in the reference documentation. The main groups:</p><table tabindex="0"><thead><tr><th>Group</th><th>Main entities</th></tr></thead><tbody><tr><td>Accounts</td><td><code>User</code>, spatie roles, role requests, individual → organisation conversions, audit log</td></tr><tr><td>Catalogue</td><td><code>Program</code>, competency blocks, price grid, QCM bank and import batches</td></tr><tr><td>Cohorts</td><td><code>Cohort</code>, trainer / coach assignments, public holidays, class sessions</td></tr><tr><td>Admission</td><td><code>Candidature</code>, steps, documents, test attempts</td></tr><tr><td>Enrolments</td><td><code>Enrolment</code>, agreements, agreement versions, consents, funding</td></tr><tr><td>Billing</td><td><code>Invoice</code>, <code>Payment</code>, <code>CreditNote</code>, remuneration, commissions, marketing contracts and invoices</td></tr><tr><td>Results</td><td>block results, jury decisions, certificates, attestations, transcripts</td></tr><tr><td>Documents</td><td>tripartite agreements, internship agreements, welcome booklets, defence reports</td></tr><tr><td>Extended activities</td><td>B2B quotes, events and registrations, company requests, profiles, incubation, partnerships</td></tr><tr><td>Integration</td><td>integration events towards Sève, sync cursors, notification deliveries</td></tr></tbody></table><p>Structural conventions:</p><ul><li>auto-incrementing integer primary keys;</li><li>amounts in FCFA, <code>DECIMAL(12,2)</code>, excluding tax;</li><li>readable yearly references (<code>FAC-NB-YYYY-XXX</code>, <code>CONV-…</code>, <code>CERT-…</code>) generated by the <code>HasYearlyReference</code> trait;</li><li>statuses carried by PHP enums, never free-form strings;</li><li>PDF documents stored on a private disk, sealed with a SHA-256 fingerprint.</li></ul><h2 id="authorisation" tabindex="-1">Authorisation <a class="header-anchor" href="#authorisation" aria-label="Permalink to &quot;Authorisation&quot;">​</a></h2><p>Authorisation is centralised in <code>AppServiceProvider</code> as named <strong>Gates</strong> (<code>view-cohorts</code>, <code>manage-billing</code>, <code>manage-incubation</code>…), backed by spatie roles. The frontend consumes the same decisions through the <code>can*</code> props shared by Inertia and the <code>useAccess</code> composable.</p><p>Three levels coexist:</p><ul><li><strong>route middleware</strong> (<code>can:manage-cohorts</code>) to block a whole section;</li><li><strong><code>Gate::authorize</code></strong> in controllers for fine-grained actions;</li><li><strong><code>abort_unless</code></strong> in a few controllers, when the rule depends on the resource rather than the role.</li></ul><p>There are no per-model Policies: the choice relies on cross-cutting Gates. See <a href="/kura-guide/en/guide/development.html#known-pitfalls">Development</a> for the guardrails to follow.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li><strong>Pages</strong> under <code>resources/js/pages</code>, one folder per module, rendered by <code>Inertia::render</code>.</li><li><strong>Shared components</strong> under <code>resources/js/components</code>: UI (buttons, cards, tables), step markers, invoice tables, segmented filters.</li><li><strong>Composables</strong>: <code>useAccess</code> (permissions), <code>useMainNav</code> (menu and groups), <code>useLocale</code>, <code>useAppearance</code>, <code>useCurrentUrl</code>.</li><li><strong>i18n</strong>: <code>vue-i18n</code>, messages in <code>resources/js/lib/locales</code>, locale driven by <code>SetLocale</code> and the profile.</li><li><strong>Wayfinder</strong>: URLs and actions are imported from <code>@/actions</code> and <code>@/routes</code>, never hard-coded.</li><li><strong>Design system</strong>: forest / green / gold palette, Plus Jakarta Sans typography, full-height sidebar, coloured status badges.</li></ul><h2 id="services-and-traits" tabindex="-1">Services and traits <a class="header-anchor" href="#services-and-traits" aria-label="Permalink to &quot;Services and traits&quot;">​</a></h2><p>Logic that doesn&#39;t fit in a model lives in <code>app/Services</code>:</p><table tabindex="0"><thead><tr><th>Service</th><th>Role</th></tr></thead><tbody><tr><td><code>Documents/DocumentLibrary</code></td><td>Lists an account&#39;s documents for “My documents”</td></tr><tr><td><code>Documents/CohortCalendar</code></td><td>Builds a cohort calendar</td></tr><tr><td><code>Seve/MoodleClient</code></td><td>REST calls to the Moodle web services</td></tr><tr><td><code>WhatsApp/WhatsAppClient</code></td><td>Sends WhatsApp Cloud API templates</td></tr><tr><td><code>Catalogue/QcmImporter</code></td><td>Imports and validates QCM banks</td></tr><tr><td><code>Direction/ActivityOverview</code></td><td>Aggregates for the Direction dashboard</td></tr><tr><td><code>Reporting/ActivityReport</code></td><td>Reporting indicators and CSV export</td></tr><tr><td><code>Partnerships/SevePartnersBlock</code></td><td>“Partners” block written into the Sève course summary</td></tr><tr><td><code>Auth/TwoFactorTicketBroker</code></td><td>Temporary two-factor authentication tickets</td></tr></tbody></table><p>The <code>HasYearlyReference</code>, <code>SealsPdf</code>, <code>PasswordValidationRules</code>, <code>ProfileValidationRules</code> and <code>AvatarValidationRules</code> traits carry cross-cutting behaviour.</p><h2 id="known-pitfalls" tabindex="-1">Known pitfalls <a class="header-anchor" href="#known-pitfalls" aria-label="Permalink to &quot;Known pitfalls&quot;">​</a></h2><p>A few inherited choices deserve attention when changing the code:</p><ul><li>some models are large (<code>Enrolment</code>, <code>Invoice</code>, <code>Cohort</code>, <code>CompanyRequest</code>) and mix queries, business rules and formatting;</li><li>list pages should load their aggregates with <code>withCount</code> / <code>withSum</code> rather than calling per-row methods (N+1 risk);</li><li>yearly numbering and payments rely on unique constraints and transactions: keep the locks and plan a retry on collision;</li><li>Inertia payloads are hand-built arrays duplicated in <code>resources/js/types</code>: evolve both together.</li></ul>`,30)])])}const g=t(o,[["render",r]]);export{h as __pageData,g as default};
